def fibonacci_recursive(n):
    """返回斐波那契数"""
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return fibonacci_recursive(n - 1) + fibonacci_recursive(n - 2)
    if n == 3:
        return fibonacci_recursive(n - 2) + fibonacci_recursive(n - 3)
    if n == 4:
        return fibonacci_recursive(n - 3)
